            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _at(a, g, m) {
            return (m >= this.START[g]) ? a[g] : this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var j, m;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var I = this.IDEA[a.idea1], F = this.FORMA[a.forma1], V = this.INV[a.inv2], N = this.FIN[a.fin2];
            var loan = (a.fin2 === 'part') ? F[4] : N[0];
            var rate = N[2] + ((a.fin2 === 'mix') ? F[5] : 0.0);
            var pay = N[1];
            var cash = c.SAV + loan - V[0] - F[0] - V[3];
            var debt = loan;
            var sales = [], recv = [];
            var cmin = cash, prof = 0.0, tot = 0.0, emerg = 0.0, fixedDec = 0.0, cmDec = 0.0;
            for (m = 1; m <= 12; m++) {
                var P = this.PRICE[this._at(a, 'precio3', m)], X = this.FIJOS[this._at(a, 'fijos3', m)];
                var D = this.DATOS[this._at(a, 'datos4', m)], K = this.CAJA[this._at(a, 'caja4', m)];
                var ramp = 1.0 - Math.exp(-m / I[1]);
                var biz = I[4];
                var dem = I[0] * ramp * V[2] * P[1] * X[2] * (biz * F[3] + (1.0 - biz));
                var cap = c.CAP * X[1] * ((a.inv2 === 'nada') ? 0.85 : 1.0);
                var units = Math.min(dem, cap);
                var resale = (m >= 2 && m <= 9) ? V[4] : 0.0;
                var s = units * P[0] + D[0] + resale * 1.15;
                var varc = units * P[0] * I[2] + resale;
                var fixed = 2 * c.DRAW + c.BASE + 2 * c.RETA * F[2] + F[1] + V[1] + X[0];
                var defer = ((m >= 9 && m <= 11) ? K[2] : 0.0) - ((m === 12) ? 3.0 * K[2] : 0.0);
                var depr = V[0] / c.DEP_YEARS / 12.0;
                var interest = debt * rate / 12.0;
                if (K[3] && m >= 9) { interest += K[3] * 0.5 * 0.09 / 12.0; }
                var one = ((m === 9) ? D[1] : 0.0) + ((m === 10) ? K[1] : 0.0) + ((m === 12) ? X[3] : 0.0) + ((m === 12) ? V[5] : 0.0);
                var cost = varc + fixed + depr + interest + one;
                prof += s - cost;
                tot += s;
                var delay = I[3] + ((m >= 9) ? K[0] : 0);
                delay = Math.max(delay, 0);
                recv.push(s);
                var collBiz = (m - 1 - delay >= 0) ? recv[m - 1 - delay] : 0.0;
                var coll = (delay > 0) ? (collBiz * biz + s * (1.0 - biz)) : s;
                var principal = (pay > 0) ? Math.max(pay - interest, 0.0) : 0.0;
                debt -= principal;
                cash += coll - (varc + fixed - defer + one + interest + principal);
                if (K[3] && m === 9) { cash += K[3]; }
                if (K[3] && m === 12) { cash -= K[3]; }
                if (cash < 0) {
                    var e = -cash * c.EMERG / 12.0;
                    emerg += e; prof -= e; cash -= e;
                }
                cmin = Math.min(cmin, cash);
                sales.push(s);
                if (m === 12) {
                    fixedDec = fixed + depr + interest;
                    cmDec = (s > 0) ? (s - varc) / s : 0.0;
                }
            }
            var be = (cmDec > 0) ? fixedDec / cmDec : 1e9;
            var dec = sales[11];
            var mos = (dec > 0) ? 100.0 * (dec - be) / dec : -100.0;
            var conf = this._clamp(c.CONF0 + I[5] + F[6] + V[6] + N[3] + this.PRICE[a.precio3][2] + this.FIJOS[a.fijos3][4]
                + this.DATOS[a.datos4][2] + this.CAJA[a.caja4][4] - ((cmin < 0) ? 6.0 : 0.0), 0.0, 100.0);
            var hard = 0;
            for (j = 0; j < this.HARD.length; j++) {
                var gk = this.HARD[j][0];
                if (a[gk] === this.HARD[j][1] && k >= this.ROUND_OF[gk]) { hard += 1; }
            }
            return { k: k, a: a, sales: sales, tot: tot, prof: prof, cmin: cmin, cash: cash, be: be, mos: mos, conf: conf,
                     dec: dec, emerg: emerg, loan: loan, hard: hard };
        }

        _components(r) {
            var c = this.C;
            var pc = this._clamp((r.prof - c.P_LO) / (c.P_HI - c.P_LO), 0, 1);
            var tc = this._clamp((r.cmin - c.T_LO) / (c.T_HI - c.T_LO), 0, 1);
            var mc = this._clamp((r.mos - c.M_LO) / (c.M_HI - c.M_LO), 0, 1);
            var sc = this._clamp((r.tot - c.S_LO) / (c.S_HI - c.S_LO), 0, 1);
            var kc = this._clamp((r.conf - c.K_LO) / (c.K_HI - c.K_LO), 0, 1);
            return [pc, tc, mc, sc, kc];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_T, c.W_M, c.W_S, c.W_K];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var sH = ds.salesHistory || [];
            var pH = ds.profitHistory || [];
            var cH = ds.cashHistory || [];
            var bH = ds.beHistory || [];
            var mH = ds.mosHistory || [];
            var kH = ds.confHistory || [];
            var n = sH.length;
            this._set('salesDisplay', n ? this._fmtMoney(sH[n - 1]) : '-');
            this._set('profitDisplay', n ? this._fmtMoney(pH[n - 1]) : '-');
            this._set('cashDisplay', n ? this._fmtMoney(cH[n - 1]) : '-');
            this._set('beDisplay', n ? this._fmtMoney(bH[n - 1]) : '-');
            this._set('mosDisplay', n ? this._fmtPct1(mH[n - 1]) : '-');
            this._set('confDisplay', n ? this._fmtInt(kH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var maps = {
                idea1: { todo: 'fb_id_todo', cuota: 'fb_id_cuota', web: 'fb_id_web', copia: 'fb_id_copia' },
                forma1: { cb: 'fb_fj_cb', sl: 'fb_fj_sl', sl1: 'fb_fj_sl1', sinalta: 'fb_fj_sinalta' },
                inv2: { local: 'fb_iv_local', min: 'fb_iv_min', stock: 'fb_iv_stock', nada: 'fb_iv_nada' },
                fin2: { ahorro: 'fb_fn_ahorro', mix: 'fb_fn_mix', part: 'fb_fn_part', tarjeta: 'fb_fn_tarjeta' },
                precio3: { bajo: 'fb_pr_bajo', coste: 'fb_pr_coste', alto: 'fb_pr_alto', gratis: 'fb_pr_gratis' },
                fijos3: { contratar: 'fb_gf_contratar', gestor: 'fb_gf_gestor', nada: 'fb_gf_nada', marketing: 'fb_gf_marketing' },
                datos4: { contrato: 'fb_dt_contrato', sin: 'fb_dt_sin', rechazar: 'fb_dt_rechazar', subcontratar: 'fb_dt_subcontratar' },
                caja4: { reservar: 'fb_cj_reservar', retrasar: 'fb_cj_retrasar', sueldos: 'fb_cj_sueldos', poliza: 'fb_cj_poliza' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                cashChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Lowest cash balance', data: [], borderColor: '#0f5e78', backgroundColor: 'rgba(15,94,120,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#0f5e78', backgroundColor: 'rgba(15,94,120,0.35)', borderWidth: 1 },
                            { label: 'Confidence and compliance', data: [], borderColor: '#b5651d', backgroundColor: 'rgba(181,101,29,0.30)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
