        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var cashHistory = ds.cashHistory || [];
            var confHistory = ds.confHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = cashHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                cashChart: {
                    labels: labels,
                    datasets: [
                        { data: cashHistory.slice(), label: this._t('chart_cash') }
                    ]
                },
                scoreChart: {
