        getHistoryTableConfig() {
            var self = this;
            var pct1 = function(v) { return self._fmtPct1(v); };
            var money = function(v) { return self._fmtMoney(v); };
            var intf = function(v) { return self._fmtInt(v); };
            return [
                { key: 'results.sales', label: 'Sales for the year', i18nKey: 'col_sales', formatter: money },
                { key: 'results.profit', label: 'Profit for the year', i18nKey: 'col_profit', formatter: money },
                { key: 'results.cash', label: 'Lowest cash balance', i18nKey: 'col_cash', formatter: money },
                { key: 'results.be', label: 'Monthly break-even', i18nKey: 'col_be', formatter: money },
                { key: 'results.mos', label: 'Margin of safety', i18nKey: 'col_mos', formatter: pct1 },
                { key: 'results.conf', label: 'Confidence and compliance', i18nKey: 'col_conf', formatter: intf },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                sales: Math.round(m.tot),
                profit: Math.round(m.prof),
                cash: Math.round(m.cmin),
                be: Math.round(m.be),
                dec: Math.round(m.dec),
                mos: this._r1(m.mos),
                conf: Math.round(m.conf),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2700-cm">'
                + '<div class="ej2700-cm-score">' + score + '<span class="ej2700-cm-max">/100</span></div>'
                + '<div class="ej2700-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2700-cm-kpis">'
