                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_profit') + ' <strong>' + this._fmtMoney(s.profit || 0) + '</strong></div>'
                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_cash') + ' <strong>' + this._fmtMoney(s.cash || 0) + '</strong></div>'
                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_be') + ' <strong>' + this._fmtMoney(s.be || 0) + '</strong></div>'
                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_dec') + ' <strong>' + this._fmtMoney(s.dec || 0) + '</strong></div>'
                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_mos') + ' <strong>' + this._fmtPct1(s.mos || 0) + '</strong></div>'
                + '<div class="ej2700-cm-kpi">' + this._t('cm_kpi_conf') + ' <strong>' + this._fmtInt(s.conf || 0) + '</strong></div>'
